import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.NwY0f7AV.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),r={name:"guide/troubleshooting.md"};function i(n,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start by turning on logging: set <code>WRAITH_DEBUG=1</code> in the environment, or pass <code>logger: true</code> to <code>createWraith()</code>. wraith then reports retries, robots.txt decisions, consent handling and other events. To watch what the browser is doing, add <code>headless: false</code>.</p><h2 id="installing-and-running" tabindex="-1">Installing and running <a class="header-anchor" href="#installing-and-running" aria-label="Permalink to &quot;Installing and running&quot;">​</a></h2><h3 id="browsertype-launch-executable-doesn-t-exist" tabindex="-1"><code>browserType.launch: Executable doesn&#39;t exist</code> <a class="header-anchor" href="#browsertype-launch-executable-doesn-t-exist" aria-label="Permalink to &quot;`browserType.launch: Executable doesn&#39;t exist`&quot;">​</a></h3><p>The browser isn&#39;t downloaded. In your project, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or firefox / webkit, for those engines</span></span></code></pre></div><p>Playwright stores browsers per version, so run it again after upgrading wraith or Playwright.</p><h3 id="err-require-esm-or-require-of-es-module" tabindex="-1"><code>ERR_REQUIRE_ESM</code> or &quot;require() of ES Module&quot; <a class="header-anchor" href="#err-require-esm-or-require-of-es-module" aria-label="Permalink to &quot;`ERR_REQUIRE_ESM` or &quot;require() of ES Module&quot;&quot;">​</a></h3><p>wraith is ESM only. Either make your project ESM (<code>&quot;type&quot;: &quot;module&quot;</code> in <code>package.json</code>, or <code>.mjs</code> files) and use <code>import</code>, or load it dynamically from CommonJS:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">createWraith</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wraithjs&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> wraith</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createWraith</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // …</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>In TypeScript, use <code>&quot;module&quot;: &quot;NodeNext&quot;</code> (or <code>&quot;Node16&quot;</code>) and <code>&quot;moduleResolution&quot;: &quot;NodeNext&quot;</code>.</p><h3 id="looks-like-you-launched-a-headed-browser-without-having-a-xserver-running" tabindex="-1">&quot;Looks like you launched a headed browser without having a XServer running&quot; <a class="header-anchor" href="#looks-like-you-launched-a-headed-browser-without-having-a-xserver-running" aria-label="Permalink to &quot;&quot;Looks like you launched a headed browser without having a XServer running&quot;&quot;">​</a></h3><p><code>headless: false</code> needs a screen, and servers and CI machines usually don&#39;t have one. Keep the default <code>headless: true</code>, or run under a virtual display: <code>xvfb-run node script.js</code>.</p><h3 id="the-process-doesn-t-exit" tabindex="-1">The process doesn&#39;t exit <a class="header-anchor" href="#the-process-doesn-t-exit" aria-label="Permalink to &quot;The process doesn&#39;t exit&quot;">​</a></h3><p>The browser is still open. Call <code>await wraith.close()</code>, ideally in a <code>finally</code> block.</p><h2 id="pages-and-actions" tabindex="-1">Pages and actions <a class="header-anchor" href="#pages-and-actions" aria-label="Permalink to &quot;Pages and actions&quot;">​</a></h2><h3 id="target-page-context-or-browser-has-been-closed" tabindex="-1">&quot;Target page, context or browser has been closed&quot; <a class="header-anchor" href="#target-page-context-or-browser-has-been-closed" aria-label="Permalink to &quot;&quot;Target page, context or browser has been closed&quot;&quot;">​</a></h3><p>The page or browser was closed while still in use: its window was closed by hand, <code>page.close()</code> or <code>wraith.close()</code> was called earlier, or the browser crashed. Open a new page with <code>wraith.open()</code> or <code>wraith.newPage()</code>.</p><h3 id="a-click-or-type-times-out" tabindex="-1">A click or type times out <a class="header-anchor" href="#a-click-or-type-times-out" aria-label="Permalink to &quot;A click or type times out&quot;">​</a></h3><p>wraith waits until the element is visible, enabled, still and uncovered. Usual causes:</p><ul><li><strong>Something covers it</strong>: a cookie banner (try <code>consent: &#39;reject&#39;</code>), a modal, a sticky header, a loading overlay.</li><li><strong>It stays disabled</strong>: the form isn&#39;t valid yet, or a previous step didn&#39;t do what you thought.</li><li><strong>The target matches a different element</strong> than you expect, often a hidden duplicate (mobile and desktop menus). Prefer <code>{ role, name }</code> targets, add <code>within</code>, or use <code>nth</code>.</li><li><strong>It&#39;s inside an iframe</strong>: build a Playwright locator with <code>page.raw.frameLocator(&#39;iframe#x&#39;).locator(&#39;button&#39;)</code> and pass that as the target.</li></ul><p>The <a href="/WRAITH/guide/devtools">devtools</a> <code>inspect</code> action shows every match, which one wraith uses, and why it isn&#39;t clickable.</p><h3 id="extract-returns-null-for-everything" tabindex="-1"><code>extract()</code> returns <code>null</code> for everything <a class="header-anchor" href="#extract-returns-null-for-everything" aria-label="Permalink to &quot;`extract()` returns `null` for everything&quot;">​</a></h3><ul><li>The content is rendered by JavaScript, and you used <code>wraith.fetch()</code>. Use a browser page.</li><li>The content loads after the page: wait for it first (<code>waitForSettled()</code>, <code>waitFor(&#39;.results&#39;)</code>).</li><li>The selector doesn&#39;t match. Check it in the browser&#39;s console: <code>document.querySelectorAll(&#39;.your-selector&#39;)</code>.</li></ul><h3 id="waitforsettled-returns-false" tabindex="-1"><code>waitForSettled()</code> returns <code>false</code> <a class="header-anchor" href="#waitforsettled-returns-false" aria-label="Permalink to &quot;`waitForSettled()` returns `false`&quot;">​</a></h3><p>The page never went quiet within the timeout: it polls, animates or streams. This is often harmless; continue anyway. To settle sooner, lower <code>networkIdleMs</code>, pass <code>loaders: false</code> if a decorative element matches a loader selector, or wait for the specific thing you need with <code>waitForText()</code> or <code>waitFor()</code>. The devtools <code>activity</code> action shows what was still busy.</p><h3 id="navigation-fails-with-httperror-http-429" tabindex="-1">Navigation fails with <code>HttpError: HTTP 429</code> <a class="header-anchor" href="#navigation-fails-with-httperror-http-429" aria-label="Permalink to &quot;Navigation fails with `HttpError: HTTP 429`&quot;">​</a></h3><p>The site is rate limiting you, and the retries didn&#39;t help. Slow down: <code>network: { rateLimit: { concurrency: 1, maxRequests: 1, intervalMs: 3000 } }</code>.</p><h3 id="browsers-can-t-log-in-to-socks-proxies" tabindex="-1">&quot;Browsers can&#39;t log in to SOCKS proxies&quot; <a class="header-anchor" href="#browsers-can-t-log-in-to-socks-proxies" aria-label="Permalink to &quot;&quot;Browsers can&#39;t log in to SOCKS proxies&quot;&quot;">​</a></h3><p>A browser instance was given a SOCKS5 proxy with a username and password, which browsers don&#39;t support. Use an HTTP proxy with that login for browser pages. The SOCKS proxy still works for static fetches.</p><h3 id="pages-fail-with-net-err-proxy-connection-failed-or-http-407" tabindex="-1">Pages fail with <code>net::ERR_PROXY_CONNECTION_FAILED</code> or HTTP 407 <a class="header-anchor" href="#pages-fail-with-net-err-proxy-connection-failed-or-http-407" aria-label="Permalink to &quot;Pages fail with `net::ERR_PROXY_CONNECTION_FAILED` or HTTP 407&quot;">​</a></h3><p>The proxy is unreachable, or rejected the login (407 Proxy Authentication Required). Check the host, port and credentials, and encode special characters in a URL login (<code>p%40ss</code> for <code>p@ss</code>), or pass <code>username</code> and <code>password</code> separately.</p><h3 id="honeypoterror" tabindex="-1"><code>HoneypotError</code> <a class="header-anchor" href="#honeypoterror" aria-label="Permalink to &quot;`HoneypotError`&quot;">​</a></h3><p><code>avoidHoneypots</code> is on, and the element is one a person couldn&#39;t see; the message says why (transparent, off the page, clipped…). If it&#39;s content that appears after a hover, click or scroll, do that first. If it&#39;s legitimate and always hidden, turn the option off for that page&#39;s work. <code>page.honeypots()</code> lists what the page has.</p><h3 id="robotsdisallowederror" tabindex="-1"><code>RobotsDisallowedError</code> <a class="header-anchor" href="#robotsdisallowederror" aria-label="Permalink to &quot;`RobotsDisallowedError`&quot;">​</a></h3><p><code>respectRobotsTxt</code> is on and the site&#39;s robots.txt disallows that URL for your user agent. Respect it, or ask the site&#39;s owner.</p><h2 id="ai" tabindex="-1">AI <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;AI&quot;">​</a></h2><h3 id="the-content-is-characters-over-the-limit" tabindex="-1">&quot;The content is … characters, over the limit&quot; <a class="header-anchor" href="#the-content-is-characters-over-the-limit" aria-label="Permalink to &quot;&quot;The content is … characters, over the limit&quot;&quot;">​</a></h3><p>The page is longer than the provider&#39;s <code>maxInputChars</code>. Pass <code>{ selector }</code> to send only the relevant part, or raise <code>ai.maxInputChars</code> if your model&#39;s context allows.</p><h3 id="ollama-calls-take-minutes" tabindex="-1">Ollama calls take minutes <a class="header-anchor" href="#ollama-calls-take-minutes" aria-label="Permalink to &quot;Ollama calls take minutes&quot;">​</a></h3><p>On a machine without a GPU, a 7B model processes a full page slowly. Narrow the input with <code>selector</code>, use a smaller model, or use a hosted provider for large pages.</p><h3 id="missingdependencyerror" tabindex="-1"><code>MissingDependencyError</code> <a class="header-anchor" href="#missingdependencyerror" aria-label="Permalink to &quot;`MissingDependencyError`&quot;">​</a></h3><p>The provider&#39;s SDK isn&#39;t installed: <code>npm install @anthropic-ai/sdk</code> or <code>npm install openai</code>.</p><h3 id="aierror" tabindex="-1"><code>AIError</code> <a class="header-anchor" href="#aierror" aria-label="Permalink to &quot;`AIError`&quot;">​</a></h3><p>The provider failed, refused, or replied with something that didn&#39;t match your schema even after a correction round. The message says which. Simpler schemas, <code>.describe()</code> hints on fields, and a narrower <code>selector</code> all help.</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p>Open an issue on <a href="https://github.com/praneth2580/WRAITH/issues" target="_blank" rel="noreferrer">GitHub</a> with the wraith version, a minimal script, and the output with <code>WRAITH_DEBUG=1</code>.</p>',47)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
